#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

// Destination-passing-style entry. The definition declares:
//   rope_theta: scalar float32
//   inv_freq  : [half_head_dim]  float32 (DPS, pre-allocated)
//
// head_dim is pinned at 128 per definition.json, so half_head_dim = 64.

void run(double rope_theta, torch::Tensor inv_freq) {
    TORCH_CHECK(inv_freq.is_cuda(), "inv_freq must be a CUDA tensor");
    TORCH_CHECK(
        inv_freq.dtype() == torch::kFloat32,
        "inv_freq must be float32, got ", inv_freq.dtype());
    TORCH_CHECK(inv_freq.is_contiguous(), "inv_freq must be contiguous");
    TORCH_CHECK(inv_freq.dim() == 1, "inv_freq must be 1D");
    TORCH_CHECK(
        inv_freq.size(0) == 64,
        "inv_freq must have 64 elements (head_dim=128/2), got ",
        inv_freq.size(0));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_016_rope_inverse_frequency_computation_launcher(
        static_cast<float>(rope_theta),
        inv_freq,
        stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "RoPE inverse-frequency computation; scalar rope_theta -> "
        "inv_freq[64] fp32; head_dim=128 pinned by problem definition; "
        "destination-passing style.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// One CTA, half_head_dim threads. Each thread computes
// `inv_freq[i] = 1.0f / powf(rope_theta, (2*i) / head_dim)`. The
// problem definition pins head_dim = 128, half_head_dim = 64.

namespace {

constexpr int HEAD_DIM = 128;
constexpr int HALF_HEAD_DIM = 64;

__global__ void __launch_bounds__(HALF_HEAD_DIM, 16)
problem_016_rope_inverse_frequency_computation_kernel(
    float rope_theta,
    float* __restrict__ inv_freq) {

    const int i = threadIdx.x;
    if (i >= HALF_HEAD_DIM) return;
    // exponent = (2 * i) / head_dim
    const float exponent =
        static_cast<float>(2 * i) / static_cast<float>(HEAD_DIM);
    // inv_freq = 1 / rope_theta^exponent
    inv_freq[i] = 1.0f / powf(rope_theta, exponent);
}

}  // namespace

void problem_016_rope_inverse_frequency_computation_launcher(
    float rope_theta,
    torch::Tensor& inv_freq,
    cudaStream_t stream) {

    dim3 grid(1);
    dim3 block(HALF_HEAD_DIM);
    problem_016_rope_inverse_frequency_computation_kernel<<<
        grid, block, 0, stream>>>(
        rope_theta,
        inv_freq.data_ptr<float>());
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the RoPE inverse-frequency-computation kernel.
// One-shot elementwise: `inv_freq[i] = 1 / rope_theta^(2*i / head_dim)`
// for i in [0, half_head_dim). Output is pre-allocated by the eval
// driver and written in-place (destination-passing style). head_dim is
// pinned at 128 per the problem definition, so half_head_dim = 64.
void problem_016_rope_inverse_frequency_computation_launcher(
    float rope_theta,
    torch::Tensor& inv_freq,
    cudaStream_t stream);
